func (this *BtseCore) ParseMarket(market any) any {
	//
	// spot
	//     {
	//         "symbol": "BTC-USDT",
	//         "type": "Spot",
	//         "category": "CRYPTO",
	//         "tradeCurrency": "BTC",
	//         "baseCurrency": "BTC",
	//         "quoteCurrency": "USDT",
	//         "displayName": "Bitcoin",
	//         "active": true,
	//         "minOrderPrice": "0.1",
	//         "minPriceIncrement": "0.1",
	//         "pricePrecision": 1,
	//         "minOrderSize": "0.00001",
	//         "maxOrderSize": "100",
	//         "minSizeIncrement": "0.00001",
	//         "sizePrecision": 5
	//     }
	//
	// swap
	//     {
	//         "symbol": "BTC-PERP-USDT",
	//         "type": "FuturesPerpetual",
	//         "category": "CRYPTO",
	//         "tradeCurrency": "BTC-PERP",
	//         "baseCurrency": "BTC",
	//         "quoteCurrency": "USDT",
	//         "displayName": "Bitcoin",
	//         "active": true,
	//         "minOrderPrice": "0.1",
	//         "minPriceIncrement": "0.1",
	//         "pricePrecision": 1,
	//         "minOrderSize": "1",
	//         "maxOrderSize": "7500000",
	//         "minSizeIncrement": "1",
	//         "sizePrecision": 0,
	//         "contractSize": "0.00001",
	//         "availableSettlement": [ "USD", "USDT" ]
	//     }
	//
	// future
	//     {
	//         "symbol": "BTC-260925-USDT",
	//         "type": "FuturesTimeBased",
	//         "category": "CRYPTO",
	//         "tradeCurrency": "BTC-260925",
	//         "baseCurrency": "BTC",
	//         "quoteCurrency": "USDT",
	//         "displayName": "Bitcoin",
	//         "active": true,
	//         "minOrderPrice": "0.1",
	//         "minPriceIncrement": "0.1",
	//         "pricePrecision": 1,
	//         "minOrderSize": "1",
	//         "maxOrderSize": "100000",
	//         "minSizeIncrement": "1",
	//         "sizePrecision": 0,
	//         "contractSize": "0.00001",
	//         "availableSettlement": [ "USD", "USDT" ],
	//         "contractStartTime": 1774569600000,
	//         "contractEndTime": 1790323230000,
	//         "matchingStartTime": 1774569615000,
	//         "becomeInactiveTime": 1790323200000
	//     }
	//
	var marketType *string = this.SafeString(market, "type")
	var isSpot bool = (marketType != nil && *marketType == "Spot")
	var isFuture bool = (marketType != nil && *marketType == "FuturesTimeBased")
	var isSwap bool = (marketType != nil && *marketType == "FuturesPerpetual")
	var id *string = this.SafeString(market, "symbol")
	var baseId *string = this.SafeString(market, "baseCurrency")
	var quoteId *string = this.SafeString(market, "quoteCurrency")
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var symbol any = Add(Add(base, "/"), quote)
	var maxAmountString *string = this.SafeString(market, "maxOrderSize")
	var minAmountString *string = this.SafeString(market, "minOrderSize")
	var minPriceString *string = this.SafeString(market, "minOrderPrice")
	var pricePrecision *string = this.SafeString(market, "minPriceIncrement")
	var amountPrecision *string = this.SafeString(market, "minSizeIncrement")
	var active any = this.SafeBool(market, "active")
	var typeVar string = "spot"
	var expiry any = nil
	var contractSize any = nil
	if !isSpot {
		symbol = Add(symbol, Add(":", quote))
		contractSize = this.SafeString(market, "contractSize")
		if isFuture {
			expiry = this.SafeInteger(market, "contractEndTime")
			symbol = Add(symbol, Add("-", this.Yymmdd(expiry)))
			typeVar = "future"
		} else {
			typeVar = "swap"
		}
	}
	var fees any = this.SafeValue(this.Fees, "contract")
	if isSpot {
		fees = this.SafeValue(this.Fees, "spot")
	}
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         Ternary(isSpot, nil, quote),
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       Ternary(isSpot, nil, quoteId),
		"type":           typeVar,
		"spot":           isSpot,
		"margin":         Ternary(isSpot, false, nil),
		"swap":           isSwap,
		"future":         isFuture,
		"option":         false,
		"active":         active,
		"contract":       isSwap || isFuture,
		"linear":         Ternary(isSpot, nil, true),
		"inverse":        Ternary(isSpot, nil, false),
		"taker":          GetValue(fees, "taker"),
		"maker":          GetValue(fees, "maker"),
		"contractSize":   this.ParseNumber(contractSize),
		"expiry":         expiry,
		"expiryDatetime": this.Iso8601(expiry),
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(amountPrecision),
			"price":  this.ParseNumber(pricePrecision),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.ParseNumber(minAmountString),
				"max": this.ParseNumber(maxAmountString),
			},
			"price": map[string]any{
				"min": this.ParseNumber(minPriceString),
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}

/**
 * @method
 * @name btse#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://docs.btse.com/markets/rest/get-klines/
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch (default and max 300)
 * @param {object} [params] extra parameters specific to the bitteam api endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *BtseCore) FetchOHLCV(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *BtseCore) fetchOHLCVBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	timeframe := GetArg(optionalArgs, 0, "1m")
	_ = timeframe
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	limit := GetArg(optionalArgs, 2, nil)
	_ = limit
	params := GetArg(optionalArgs, 3, map[string]any{})
	_ = params

	retRes8218 := (<-this.LoadMarkets())
	PanicOnError(retRes8218)
	var maxLimit any = 300
	var paginate any = false
	paginateparamsVariable := this.HandleOptionAndParams(params, "fetchOHLCV", "paginate")
	paginate = GetValue(paginateparamsVariable, 0)
	params = GetValue(paginateparamsVariable, 1)
	if EvalTruthy(paginate) {

		ch <- this.FetchPaginatedCallDeterministic("fetchOHLCV", symbol, since, limit, timeframe, params, maxLimit)
		return nil
	}
	var market any = this.Market(symbol)
	var interval *string = this.SafeString(this.Timeframes, timeframe, timeframe)
	var request map[string]any = map[string]any{
		"symbol":     GetValue(market, "id"),
		"resolution": interval,
	}
	if !IsEqual(limit, nil) {
		AddElementToObject(request, "limit", mathMin(limit, maxLimit))
	} else {
		// the endpoint returns only 10 candles when the limit is omitted
		AddElementToObject(request, "limit", maxLimit)
	}
	if !IsEqual(since, nil) {
		// the endpoint accepts timestamps in seconds
		AddElementToObject(request, "start", this.ParseToInt(Divide(since, 1000)))
	}
	var until any = nil
	untilparamsVariable := this.HandleOptionAndParams(params, "fetchOHLCV", "until")
	until = GetValue(untilparamsVariable, 0)
	params = GetValue(untilparamsVariable, 1)
	if !IsEqual(until, nil) {
		if !IsEqual(since, nil) {
			// check if the requested time range is too large for one request
			// if so, just omit until for correct paginated calls for not to get an error from the exchange
			var duration any = this.ParseTimeframe(timeframe)
			var maxDelta any = Multiply(Multiply(duration, maxLimit), 1000) // parseTimeframe returns seconds, the difference below is in milliseconds
			var difference any = Subtract(until, since)
			if IsLessThan(difference, maxDelta) {
				AddElementToObject(request, "end", this.ParseToInt(Divide(until, 1000)))
			}
		} else {
			AddElementToObject(request, "end", this.ParseToInt(Divide(until, 1000)))
		}
	}

	response := (<-this.PublicGetPublicApiMarketV1Klines(this.Extend(request, params)))
	PanicOnError(response)
	//
	//     {
	//         "data": [
	//             [
	//                 "1786600800",
	//                 "1895.78",
	//                 "1898.52",
	//                 "1892.05",
	//                 "1898.3",
	//                 "560622.306372"
	//             ]
	//         ],
	//         "code": 1,
	//         "msg": "Success",
	//         "success": true,
	//         "time": 1786604274378
	//     }
	//
	var data any = this.SafeList(response, "data", []any{})
	var result any = this.ParseOHLCVs(data, market, timeframe, since, limit)

	ch <- result
	return nil
}
func (this *BtseCore) ParseOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//     [
	//         "1786600800", // timestamp in seconds
	//         "1895.78",
	//         "1898.52",
	//         "1892.05",
	//         "1898.3",
	//         "560622.306372" // volume in quote currency, contract rows may use scientific notation
	//     ]
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	return []any{this.SafeTimestamp(ohlcv, 0), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 4), this.SafeNumber(ohlcv, 5)}
}

