/**
 * @method
 * @name btse#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://docs.btse.com/markets/rest/get-funding-rate-history/
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch, used to select the requested period and then applied client-side
 * @param {int} [limit] the maximum amount of entries to fetch, applied client-side
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.period] the funding rate history period, one of '7D', '2W' or '1M', selected from since by default
 * @param {int} [params.until] timestamp in ms of the latest funding rate to fetch, applied client-side
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
 */
func (this *BtseCore) FetchFundingRateHistory(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *BtseCore) fetchFundingRateHistoryBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbol := GetArg(optionalArgs, 0, nil)
	_ = symbol
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	limit := GetArg(optionalArgs, 2, nil)
	_ = limit
	params := GetArg(optionalArgs, 3, map[string]any{})
	_ = params
	if IsEqual(symbol, nil) {
		panic(ArgumentsRequired(Add(this.Id, " fetchFundingRateHistory() requires a symbol argument")))
	}

	retRes9648 := (<-this.LoadMarkets())
	PanicOnError(retRes9648)
	var market any = this.Market(symbol)
	if !EvalTruthy((GetValue(market, "contract"))) {
		panic(BadRequest(Add(this.Id, " fetchFundingRateHistory() supports contract markets only")))
	}
	var period any = nil
	periodparamsVariable := this.HandleOptionAndParams(params, "fetchFundingRateHistory", "period")
	period = GetValue(periodparamsVariable, 0)
	params = GetValue(periodparamsVariable, 1)
	if IsEqual(period, nil) {
		period = "7D"
		if !IsEqual(since, nil) {
			var age any = Subtract(this.Milliseconds(), since)
			var day any = 86400000
			if IsGreaterThan(age, Multiply(14, day)) {
				period = "1M"
			} else if IsGreaterThan(age, Multiply(7, day)) {
				period = "2W"
			}
		}
	}
	var request map[string]any = map[string]any{
		"symbol": GetValue(market, "id"),
		"period": period,
	}
	var until any = nil
	untilparamsVariable := this.HandleOptionAndParams(params, "fetchFundingRateHistory", "until")
	until = GetValue(untilparamsVariable, 0)
	params = GetValue(untilparamsVariable, 1)

	response := (<-this.PublicGetPublicApiMarketV1RecentFundingHistory(this.Extend(request, params)))
	PanicOnError(response)
	//
	//     {
	//         "data": [
	//             {
	//                 "timestamp": 1786003200911,
	//                 "rate": "0.0000152"
	//             }
	//         ],
	//         "code": 1,
	//         "msg": "Success",
	//         "success": true,
	//         "time": 1786607775380
	//     }
	//
	var data any = this.SafeList(response, "data", []any{})
	var rates any = this.ParseFundingRateHistories(data, market, since, limit)
	if IsEqual(until, nil) {

		ch <- rates
		return nil
	}
	var result any = []any{}
	for i := 0; IsLessThan(i, GetArrayLength(rates)); i++ {
		var rate any = GetValue(rates, i)
		var timestamp *int64 = this.SafeInteger(rate, "timestamp")
		if (timestamp == nil) || (IsLessThanOrEqual(timestamp, until)) {
			AppendToArray(&result, rate)
		}
	}

	ch <- result
	return nil
}
func (this *BtseCore) ParseFundingRateHistory(contract any, optionalArgs ...any) any {
	//
	//     {
	//         "timestamp": 1786003200911,
	//         "rate": "0.0000152"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(contract, "timestamp")
	return map[string]any{
		"info":        contract,
		"symbol":      this.SafeSymbol(nil, market),
		"fundingRate": this.SafeNumber(contract, "rate"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
	}
}

