func (this *BtseCore) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//     {
	//         "id": 91151062,
	//         "timestamp": 1786605669577,
	//         "price": "1896.3291755587",
	//         "size": "0.06",
	//         "quoteSize": "113.7797505335",
	//         "side": "BUY"
	//     }
	//
	// fetchMyTrades spot
	//     {
	//         "tradeId": "4b4bd301-6f20-4e39-a682-ce4f9b8400a0",
	//         "orderId": "2fa9678b-9945-47ce-9ffe-256dc7b4dd8c",
	//         "clOrderID": "test spot market buy",
	//         "username": "romancuhari",
	//         "side": "BUY",
	//         "orderType": 77,
	//         "triggerType": 0,
	//         "price": 1952.05859608,
	//         "size": 0.19520586,
	//         "filledPrice": 1952.05859608,
	//         "filledSize": 0.0001,
	//         "triggerPrice": 0,
	//         "base": "ETH",
	//         "quote": "USDT",
	//         "symbol": "ETH-USDT",
	//         "feeCurrency": "ETH",
	//         "feeAmount": 0.0000002,
	//         "wallet": "SPOT@",
	//         "realizedPnl": 0,
	//         "total": 0,
	//         "serialId": 49071052,
	//         "timestamp": 1770814978685,
	//         "avgFilledPrice": 1952.05859608
	//     }
	//
	// fetchMyTrades swap
	//     {
	//         "tradeId": "b708489a-19d1-4be2-a6c2-f499f76aa176",
	//         "orderId": "5c6a26db-8cfb-45c7-b25d-56927bc36795",
	//         "username": "romancuhari",
	//         "side": "BUY",
	//         "orderType": 77,
	//         "triggerType": null,
	//         "price": 0,
	//         "size": 1,
	//         "filledPrice": 1956.59,
	//         "filledSize": 1,
	//         "triggerPrice": 0,
	//         "base": "ETH",
	//         "quote": "USDT",
	//         "symbol": "ETH-PERP",
	//         "feeCurrency": "USDT",
	//         "feeAmount": 0.00010761,
	//         "wallet": "CROSS@",
	//         "realizedPnl": 0,
	//         "total": -0.00010761,
	//         "serialId": 50953296,
	//         "timestamp": 1770821231984,
	//         "orderDetailType": null,
	//         "contractSize": 0.0001,
	//         "clOrderID": "",
	//         "positionId": "ETH-PERP-USDT",
	//         "avgFilledPrice": 1956.59
	//     }
	//
	// the unified futures rows echo the short symbol form but carry the full
	// market id in positionId, which resolves against the markets snapshot
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString2(trade, "positionId", "symbol")
	market = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(trade, "timestamp")
	var fee any = nil
	var feeCost any = this.SafeNumber(trade, "feeAmount")
	if !IsEqual(feeCost, nil) {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": this.SafeCurrencyCode(this.SafeString(trade, "feeCurrency")),
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"id":           this.SafeStringN(trade, []any{"tradeId", "serialId", "id"}),
		"order":        this.SafeString(trade, "orderId"),
		"type":         this.ParseOrderType(this.SafeString2(trade, "orderType", "type")),
		"side":         this.SafeStringLower2(trade, "side", "orderSide"),
		"takerOrMaker": nil,
		"price":        this.SafeStringN(trade, []any{"filledPrice", "avgFilledPrice", "price"}),
		"amount":       this.SafeString2(trade, "filledSize", "size"),
		"cost":         nil,
		"fee":          fee,
	}, market)
}

