func (this *BtseCore) ParseOrder(order any, optionalArgs ...any) any {
	//
	// createOrder - spot
	//     {
	//         "status": 2,
	//         "symbol": "ETH-USDT",
	//         "orderType": 76,
	//         "price": 1000,
	//         "side": "BUY",
	//         "orderID": "cde4fb37-2e2b-437e-a816-4b55b2e2b7c7",
	//         "timestamp": 1770813053751,
	//         "triggerPrice": 0,
	//         "stopPrice": null,
	//         "trigger": false,
	//         "message": "",
	//         "clOrderID": null,
	//         "stealth": 1,
	//         "deviation": 1,
	//         "postOnly": false,
	//         "orderDetailType": null,
	//         "originalOrderBaseSize": 0.0001,
	//         "originalOrderQuoteSize": null,
	//         "currentOrderBaseSize": 0.0001,
	//         "currentOrderQuoteSize": null,
	//         "remainingOrderBaseSize": 0.0001,
	//         "remainingOrderQuoteSize": null,
	//         "filledBaseSize": 0,
	//         "totalFilledBaseSize": 0,
	//         "orderCurrency": "base",
	//         "avgFilledPrice": 0,
	//         "time_in_force": "GTC"
	//     }
	//
	// createOrder - swap
	//     {
	//         "status": 4,
	//         "symbol": "ETH-PERP",
	//         "orderType": 77,
	//         "price": 1956.59,
	//         "side": "BUY",
	//         "orderID": "5c6a26db-8cfb-45c7-b25d-56927bc36795",
	//         "timestamp": 1770821231984,
	//         "triggerPrice": 0,
	//         "trigger": false,
	//         "deviation": 100,
	//         "stealth": 100,
	//         "message": "",
	//         "avgFilledPrice": 1956.59,
	//         "clOrderID": "",
	//         "originalOrderSize": 1,
	//         "currentOrderSize": 1,
	//         "filledSize": 1,
	//         "totalFilledSize": 1,
	//         "remainingSize": 0,
	//         "postOnly": false,
	//         "orderDetailType": null,
	//         "positionMode": "ONE_WAY",
	//         "positionDirection": null,
	//         "positionId": "ETH-PERP-USDT",
	//         "time_in_force": "GTC"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString2(order, "symbol", "market")
	market = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(order, "timestamp")
	// open_orders rows carry no numeric status - the state lives in
	// orderState (STATUS_ACTIVE / STATUS_INACTIVE), and time_in_force
	// is spelled timeInForce there (observed live), so both fall back
	var rawStatus *string = this.SafeString2(order, "status", "orderState")
	var rawType *string = this.SafeString2(order, "orderType", "type")
	var status any = this.ParseOrderStatus(rawStatus)
	var orderType any = this.ParseOrderType(rawType)
	if (IsEqual(orderType, "market")) && (IsEqual(status, "open")) {
		// market orders never rest on the book, the exchange reports the
		// partially filled code on them when a residual quote dust amount
		// cannot fill, observed live, such orders are finished
		status = "closed"
	}
	var rawTimeInForce *string = this.SafeString2(order, "time_in_force", "timeInForce")
	return this.SafeOrder(map[string]any{
		"info":                order,
		"id":                  this.SafeString2(order, "orderID", "orderId"),
		"clientOrderId":       this.SafeString2(order, "clOrderID", "clOrderId"),
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastTradeTimestamp":  nil,
		"lastUpdateTimestamp": nil,
		"status":              status,
		"symbol":              GetValue(market, "symbol"),
		"type":                orderType,
		"timeInForce":         this.ParseTimeInForce(rawTimeInForce),
		"postOnly":            this.SafeBool(order, "postOnly"),
		"reduceOnly":          this.SafeBool(order, "reduceOnly"),
		"side":                this.SafeStringLower2(order, "side", "orderSide"),
		"price":               this.SafeString2(order, "price", "orderPrice"),
		"triggerPrice":        this.OmitZero(this.SafeString2(order, "triggerOriginalPrice", "triggerPrice")),
		"stopLossPrice":       nil,
		"takeProfitPrice":     nil,
		"amount":              this.SafeStringN(order, []any{"currentOrderBaseSize", "currentOrderSize", "orderSize"}),
		"filled":              this.SafeStringN(order, []any{"totalFilledBaseSize", "totalFilledSize", "filledSize"}),
		"remaining":           this.SafeString2(order, "remainingOrderBaseSize", "remainingSize"),
		"cost":                nil,
		"trades":              nil,
		"fee":                 nil,
		"average":             this.OmitZero(this.SafeString2(order, "avgFilledPrice", "averageFillPrice")),
	}, market)
}
func (this *BtseCore) ParseOrderStatus(status any) any {
	var statuses map[string]any = map[string]any{
		"2":                          "open",
		"3":                          "closed",
		"4":                          "closed",
		"5":                          "open",
		"6":                          "canceled",
		"7":                          "refunded",
		"8":                          "rejected",
		"9":                          "open",
		"10":                         "open",
		"15":                         "rejected",
		"16":                         "rejected",
		"17":                         "rejected",
		"123":                        "open",
		"STATUS_ACTIVE":              "open",
		"STATUS_INACTIVE":            "canceled",
		"ORDER_INSERTED":             "open",
		"ORDER_PARTIALLY_TRANSACTED": "open",
		"ORDER_FULLY_TRANSACTED":     "closed",
		"ORDER_CANCELLED":            "canceled",
	}
	return this.SafeString(statuses, status, status)
}
