func (this *BtseCore) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	//     {
	//         "username": "user",
	//         "orderId": "2026081200000367",
	//         "wallet": "SPOT@",
	//         "currency": "USDT",
	//         "type": "Deposit",
	//         "amount": 100,
	//         "fees": 0,
	//         "description": "",
	//         "timestamp": 1786510157962,
	//         "status": "PROCESSING",
	//         "txId": "",
	//         "toAddress": "0x0000000000000000000000000000000000000000",
	//         "currencyNetwork": "",
	//         "sourceCurrency": "USDT",
	//         "sourceAmount": 0,
	//         "targetCurrency": "",
	//         "targetAmount": 0,
	//         "rate": 0
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId *string = this.SafeString2(transaction, "currency", "asset")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp *int64 = this.SafeInteger2(transaction, "timestamp", "transactionTime")
	var networkId *string = this.SafeString2(transaction, "currencyNetwork", "cryptoNetwork")
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString2(transaction, "orderId", "transactionRef"),
		"txid":        this.SafeString(transaction, "txId"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     this.NetworkIdToCode(networkId, code),
		"address":     this.SafeString(transaction, "toAddress"),
		"addressTo":   this.SafeString(transaction, "toAddress"),
		"addressFrom": nil,
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        this.ParseTransactionType(this.SafeString(transaction, "type")),
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      this.ParseTransactionStatus(this.SafeString(transaction, "status")),
		"updated":     nil,
		"internal":    nil,
		"comment":     this.SafeString(transaction, "description"),
		"fee": map[string]any{
			"currency": code,
			"cost":     this.SafeNumber2(transaction, "fees", "fee"),
		},
	}
}
